"use client";

import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import { getLength, getPointAtLength } from "@remotion/paths";
import type React from "react";
import { useId } from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_INPUT,
  HIDDEN,
  inputTokens,
  type NeuralPulseElementId,
  neuralPulseTimeline,
} from "./timeline";

const { fontFamily: mono } = loadMono("normal", {
  weights: ["400"],
  subsets: ["latin"],
});
const manrope = loadManrope("normal", {
  weights: ["500", "600"],
  subsets: ["latin"],
});

const REMOCN_R_PATH =
  "M 0.01 0.81 C 0.01 1.73, 0.36 2.79, 1.09 4.13 C 4.91 11.04, 13.45 17.16, 21.7 18.9 C 22.94 19.16, 23.18 19.16, 51.39 19.27 C 76.07 19.36, 80.02 19.4, 81.32 19.57 C 89.89 20.69, 96.2 24.68, 99.38 31.01 C 103.19 38.56, 102.53 50.1, 97.91 57.07 C 94.66 61.96, 89.68 64.99, 83.26 66 C 82.81 66.07, 70.18 66.83, 55.2 67.69 C 24.82 69.43, 27.03 69.23, 24.18 70.4 C 19.9 72.15, 14.84 75.7, 10.65 79.89 C 4.86 85.68, 1.3 91.91, 0.25 98.13 C 0.12 98.85, 0.08 103.13, 0.04 116.66 L 0 134.26 9.5 134.26 L 19 134.26 19.05 119.41 C 19.1 103.27, 19.08 103.82, 19.82 101.04 C 21.79 93.65, 27.86 88.75, 36.45 87.63 C 37.23 87.53, 39.41 87.5, 43.57 87.53 C 50.12 87.59, 50.75 87.65, 53.22 88.45 C 56.61 89.56, 59.67 91.86, 62.02 95.07 C 62.52 95.76, 69.35 103.85, 77.2 113.07 C 85.04 122.28, 91.63 130.04, 91.85 130.32 C 92.07 130.59, 92.5 131.34, 92.82 131.97 C 93.52 133.35, 94.11 133.93, 95.06 134.13 C 95.5 134.23, 98.97 134.26, 106.36 134.23 L 117.01 134.19 100.82 113.07 C 91.91 101.45, 84.52 91.78, 84.39 91.57 C 83.36 89.89, 83.66 87.53, 85.09 86 C 85.79 85.25, 86.36 84.94, 88.07 84.38 C 96.18 81.72, 104.15 76.62, 109.97 70.36 C 120.59 58.93, 124.06 44.32, 119.44 30.43 C 114.59 15.81, 101.93 4.02, 87.64 0.83 C 83.93 0.01, 88.09 0.08, 41.85 0.04 L 0.01 0 0.01 0.81 Z";
const R_W = 124.06;
const R_H = 134.26;
const R_LEN = getLength(REMOCN_R_PATH);
/** Manrope 600 advance of "emocn" at -0.025em tracking, in em. */
const EMOCN_EM = 3.146;

export interface NeuralPulseProps {
  /** The prompt that enters the network. Split on spaces into tokens (max 5). */
  input?: string;
  /** What the network resolves to: a product name or a short answer. */
  output?: string;
  /** Replaces the remocn R mark next to the output. */
  logo?: React.ReactNode;
  accent?: string;
  /** Color of the tokens and the output; overrides the theme ink. */
  ink?: string;
  /** Stage fill; "transparent" drops it with the beam and grain. */
  background?: string;
  /** Typeface for the output. Load it yourself; Manrope by default. */
  fontFamily?: string;
  /** Frames for the pulse to hop from one layer to the next. */
  hop?: number;
  /** Size of the network and lockup, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the tokens, the network, the pulse's hops, the
   * camera and the logo trace, by the ids in `./timeline`.
   * Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<NeuralPulseElementId>;
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "beam" palette: bg #02030a, [#f4f7ff, #8fb4ff, #3d5bff, #1a1660]
const PALETTES = {
  dark: {
    bg: "#02030a",
    fg: [243, 244, 250],
    muted: "#8B8A90",
    token: "rgba(143,180,255,0.05)",
    grain: 0.06,
    beam: [
      [26, 22, 96, 0.55],
      [61, 91, 255, 0.3],
      [143, 180, 255, 0.16],
    ],
    rFill: ["#f4f7ff", "#8fb4ff", "#3d5bff"],
  },
  light: {
    bg: "#F5F4F0",
    fg: [18, 18, 24],
    muted: "#6E6C67",
    token: "rgba(255,255,255,0.75)",
    grain: 0.04,
    beam: [
      [143, 180, 255, 0.22],
      [61, 91, 255, 0.1],
      [244, 247, 255, 0.9],
    ],
    rFill: ["#1a1660", "#3d5bff", "#8fb4ff"],
  },
} as const;

type Palette = (typeof PALETTES)[keyof typeof PALETTES];

/**
 * A move from where layout holds an element at rest, or nothing at all once
 * it's under a thousandth of a pixel: layout rounds a box to whole pixels, so
 * anything eased by `left`/`top` clicks along; a transform glides.
 */
const shift = (x: number, y: number) =>
  Math.abs(x) < 1e-3 && Math.abs(y) < 1e-3 ? "" : `translate(${x}px, ${y}px) `;

function hash(n: number) {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}

const rgba = (c: readonly number[], a: number) =>
  `rgba(${c[0]},${c[1]},${c[2]},${Math.max(0, Math.min(1, a))})`;

interface Node3 {
  x: number;
  y: number;
  z: number;
  act: number;
}

interface Edge {
  k: number;
  i: number;
  j: number;
  w: number;
  start: number;
  primary: boolean;
}

/** Deterministic layered net: positions, attention weights, activations, path. */
function buildNet(tokenLengths: number[], u: number, layerStarts: number[]) {
  const tokens = tokenLengths.length;
  const longest = Math.max(...tokenLengths);
  const sizes = [tokens, ...HIDDEN, 1];
  const layers: Node3[][] = sizes.map((n, k) => {
    const spacing = Math.min(86, 440 / Math.max(1, n - 1)) * u;
    return Array.from({ length: n }, (_, i) => {
      const edge = k === 0 || k === sizes.length - 1;
      return {
        x: (-330 + k * 165) * u,
        y:
          (i - (n - 1) / 2) * spacing +
          (edge ? 0 : (hash(k * 31 + i) - 0.5) * 18 * u),
        z: edge ? 0 : (hash(k * 17 + i * 7 + 3) - 0.5) * 420 * u,
        act: k === 0 ? 0.35 + (0.65 * tokenLengths[i]) / longest : 0,
      };
    });
  });
  const weight = (k: number, i: number, j: number) =>
    hash(k * 1000 + i * 37 + j * 101 + 7) ** 2.2;
  for (let k = 1; k < sizes.length; k++) {
    let max = 0;
    for (const [j, node] of layers[k].entries()) {
      node.act = layers[k - 1].reduce(
        (s, prev, i) => s + prev.act * weight(k - 1, i, j),
        0,
      );
      max = Math.max(max, node.act);
    }
    for (const node of layers[k]) node.act = max > 0 ? node.act / max : 0;
  }
  // attention path: forward from the heaviest token, strongest weight * activation
  const path = new Set<string>();
  const primaryToken = tokenLengths.indexOf(longest);
  let at = primaryToken;
  for (let k = 0; k < sizes.length - 1; k++) {
    let best = -1;
    let bestJ = 0;
    for (const [j, node] of layers[k + 1].entries()) {
      const s = node.act * weight(k, at, j);
      if (s > best) {
        best = s;
        bestJ = j;
      }
    }
    path.add(`${k}-${at}-${bestJ}`);
    at = bestJ;
  }
  const edges: Edge[] = [];
  for (let k = 0; k < sizes.length - 1; k++) {
    for (let i = 0; i < sizes[k]; i++) {
      for (let jj = 0; jj < sizes[k + 1]; jj++) {
        edges.push({
          k,
          i,
          j: jj,
          w: weight(k, i, jj),
          start: layerStarts[k] + Math.round(hash(k * 7 + i * 13 + jj) * 3),
          primary: path.has(`${k}-${i}-${jj}`),
        });
      }
    }
  }
  return { layers, edges, primaryToken };
}

/** When the pulse lights layer `k`: the inputs fire with the first hop. */
function arrival(
  k: number,
  hops: { start: number; beat(name: string): number }[],
) {
  return k === 0
    ? hops[0].start
    : hops[k - 1].start + hops[k - 1].beat("arrive");
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={11}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

export function NeuralPulse(props: NeuralPulseProps) {
  const {
    input = DEFAULT_INPUT,
    output = "remocn",
    logo,
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = manrope.fontFamily,
    scale = 1,
    delay = 0,
    grain = true,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    neuralPulseTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const drift = tl.get("drift");
  const network = tl.get("network");
  const splitEl = tl.get("split");
  const flyEl = tl.get("fly");
  const fireEl = tl.get("fire");
  const hops = tl.lane("Network").filter((e) => e.id.startsWith("layer:"));
  const resolveEl = tl.get("resolve");
  const trace = tl.get("trace");
  const nameEl = tl.get("name");
  const u = height / 720;
  const p: Palette = PALETTES[theme];
  const fg = p.fg;
  const transparent = background === "transparent";

  const tokens = inputTokens(input);
  const { layers, edges, primaryToken } = buildNet(
    tokens.map((tk) => tk.length),
    u,
    hops.map((e) => e.start),
  );
  const outK = layers.length - 1;

  const f = 1500 * u;
  const T_TRACE = trace.start;
  // Drift, resolve, trace and the name all clamp by here.
  const T_REST = Math.max(...tl.elements.map((e) => e.end));

  // final lockup: the real logo (R mark + "emocn" in Manrope), centered.
  // The output node lands on the R's first anchor and traces its outline.
  const brand = !logo && output.trim().toLowerCase() === "remocn";
  const word = brand ? "emocn" : output;
  const wordEm = brand ? EMOCN_EM : word.length * 0.63;
  const nameSize = Math.min(height * 0.175, (width * 0.6) / (0.74 + wordEm));
  const markH = nameSize * 0.76;
  const markW = logo ? markH : (markH * R_W) / R_H;
  const gap = nameSize * (brand ? 0.04 : 0.24);
  const groupW = markW + gap + wordEm * nameSize;
  const markLeft = width / 2 - groupW / 2;
  const baselineY = height / 2 + nameSize * 0.36;
  const markTop = baselineY - markH;
  const rk = markH / R_H;
  const toScreen = (pt: { x: number; y: number }) => ({
    x: markLeft + pt.x * rk,
    y: markTop + pt.y * rk,
  });
  const dotTarget = logo
    ? { x: markLeft + markW / 2, y: markTop + markH / 2 }
    : toScreen({ x: 0.01, y: 0.81 });
  // ---- camera: slow yaw drift, gentle pitch, then truck + push at resolve
  const camAt = (tt: number) => {
    const drifted = interpolate(tt, [drift.start, drift.end], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
    const yaw = ((-26 + drifted * 30) * Math.PI) / 180;
    const pitch = ((7 - drifted * 4) * Math.PI) / 180;
    const resolveP = interpolate(
      tt,
      [resolveEl.start + resolveEl.beat("pull"), resolveEl.end],
      [0, 1],
      {
        ...CLAMP,
        easing: EASE_IO,
      },
    );
    const dolly = -resolveP * 160 * u;
    const rawProject = (n: { x: number; y: number; z: number }) => {
      const cyw = Math.cos(yaw);
      const syw = Math.sin(yaw);
      const x = n.x * cyw + n.z * syw;
      let z = -n.x * syw + n.z * cyw;
      const cp = Math.cos(pitch);
      const sp = Math.sin(pitch);
      const y = n.y * cp - z * sp;
      z = n.y * sp + z * cp + dolly;
      const s = f / (f - z);
      return { x: width / 2 + x * s, y: height / 2 + y * s, s, z };
    };
    const outRaw = rawProject(layers[outK][0]);
    const panX = (dotTarget.x - outRaw.x) * resolveP;
    const panY = (dotTarget.y - outRaw.y) * resolveP;
    const project = (n: { x: number; y: number; z: number }) => {
      const r = rawProject(n);
      return { ...r, x: r.x + panX, y: r.y + panY };
    };
    return { resolveP, proj: layers.map((layer) => layer.map(project)) };
  };
  type Cam = ReturnType<typeof camAt>;
  const cam = camAt(t);
  const { resolveP, proj } = cam;
  // Where everything rests: layout holds each moving piece there, and the
  // way there is a transform.
  const camRest = camAt(T_REST);

  // network focus: soft at the open, sharp while firing, defocused behind the title
  const netBlur =
    interpolate(
      t,
      [
        network.start + network.beat("focusFrom"),
        network.start + network.beat("focusTo"),
      ],
      [3.2, 0],
      { ...CLAMP, easing: EASE_IO },
    ) +
    resolveP * 5;
  const netOpacity = 1 - resolveP * 0.7;

  const intro = (k: number, i: number) => {
    const at =
      network.start + k * network.beat("layer") + i * network.beat("node");
    return interpolate(t, [at, at + network.length], [0, 1], CLAMP);
  };

  const nodeLit = (k: number, i: number, tt = t) => {
    const a = arrival(k, hops);
    const act = k === 0 ? 1 : layers[k][i].act;
    const env = interpolate(tt, [a, a + 4, a + 26], [0, 1, 0.4], CLAMP);
    const bloom = interpolate(tt, [a, a + 5, a + 18], [0, 1, 0], CLAMP);
    return { lit: env * act, bloom: bloom * act };
  };

  const onPath = (k: number, i: number) => {
    if (k === outK) return true;
    if (k === 0) return i === primaryToken;
    return edges.some((e) => e.primary && e.k === k && e.i === i);
  };

  // ---- edges + pulses (SVG)
  const edgeEls: React.ReactNode[] = [];
  const pulseEls: React.ReactNode[] = [];
  for (const e of edges) {
    const travel = hops[e.k].beat("travel");
    const a = proj[e.k][e.i];
    const b = proj[e.k + 1][e.j];
    const depth = interpolate(
      (a.s + b.s) / 2,
      [0.85, 1.15],
      [0.55, 1.1],
      CLAMP,
    );
    const on = Math.min(intro(e.k, e.i), intro(e.k + 1, e.j));
    const env = interpolate(
      t,
      [e.start, e.start + travel * 0.6, e.start + travel + 22],
      [0, 1, e.primary ? 0.7 : 0.18],
      CLAMP,
    );
    const strength = e.primary ? 1 : e.w ** 1.4;
    const base = 0.06 * depth * on;
    const lit = env * strength * (e.primary ? 0.95 : 0.5) * depth;
    edgeEls.push(
      <line
        key={`e${e.k}-${e.i}-${e.j}`}
        x1={a.x}
        y1={a.y}
        x2={b.x}
        y2={b.y}
        stroke={e.primary && env > 0 ? accent : rgba(fg, 1)}
        strokeOpacity={e.primary && env > 0 ? lit : base + lit}
        strokeWidth={(e.primary ? 1.6 : 1) * u * depth}
      />,
    );
    if (e.primary || e.w > 0.38) {
      const raw = (t - e.start) / travel;
      for (let g = 0; g < 4; g++) {
        const q = raw - g * 0.06;
        if (q <= 0 || q >= 1) continue;
        const qe = EASE_IO(q);
        const fade = Math.min(1, (1 - q) * 6) * Math.min(1, q * 8);
        pulseEls.push(
          <circle
            key={`p${e.k}-${e.i}-${e.j}-${g}`}
            cx={a.x + (b.x - a.x) * qe}
            cy={a.y + (b.y - a.y) * qe}
            r={(e.primary ? 3 : 2.2) * u * depth * (1 - g * 0.18)}
            fill={e.primary ? accent : rgba(fg, 1)}
            opacity={
              fade *
              (g === 0 ? 1 : 0.42 / g) *
              (e.primary ? 1 : 0.4 + e.w * 0.6)
            }
          />,
        );
      }
    }
  }

  // ---- tokens: sentence -> tokenized -> column at the input nodes -> fired
  const tokSize = 25 * u;
  const pad = 13 * u;
  const tokW = tokens.map((tk) => tk.length * tokSize * 0.6 + pad * 2);
  const splitAt = (tt: number) =>
    interpolate(tt, [splitEl.start, splitEl.end], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  const split = splitAt(t);
  const colScale = 0.66;
  const tokenGeo = (tt: number, c: Cam) => {
    const gapX = (4 + splitAt(tt) * 10) * u;
    const rowW = tokW.reduce((s, w) => s + w, 0) + gapX * (tokens.length - 1);
    let cursor = width / 2 - rowW / 2;
    return tokens.map((_, i) => {
      const flyAt = flyEl.start + i * flyEl.beat("stagger");
      const fly = interpolate(
        tt,
        [flyAt, flyAt + flyEl.beat("flight")],
        [0, 1],
        {
          ...CLAMP,
          easing: EASE_IO,
        },
      );
      const node = c.proj[0][i];
      const startX = cursor;
      cursor += tokW[i] + gapX;
      const endX = node.x - 26 * u - tokW[i] * colScale;
      const tokenEl = tl.get(`token:${i}`);
      const appear = interpolate(tt, [tokenEl.start, tokenEl.end], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      return {
        x: startX + (endX - startX) * fly,
        y: height / 2 + (node.y - height / 2) * fly,
        sc: 1 + (colScale - 1) * fly,
        lift: (1 - appear) * 10 * u,
        appear,
        fly,
        endX,
        node,
      };
    });
  };
  const toks = tokenGeo(t, cam);
  const toksRest = tokenGeo(T_REST, camRest);
  const toksPrev = tokenGeo(t - speed, camAt(t - speed));
  const toksNext = tokenGeo(t + speed, camAt(t + speed));
  const tokenEls = tokens.map((tk, i) => {
    const { x, y, sc, lift, appear, fly, endX, node } = toks[i];
    const rest = toksRest[i];
    const gone = (a: (typeof toks)[number], b: (typeof toks)[number]) =>
      Math.max(
        Math.abs(a.x - b.x),
        Math.abs(a.y - b.y),
        Math.abs(a.sc - b.sc) * tokW[i],
        Math.abs(a.lift - b.lift),
      ) > 1e-3;
    const moving = gone(toks[i], toksPrev[i]) || gone(toks[i], toksNext[i]);
    const fireAt = fireEl.start + i * fireEl.beat("stagger");
    const fire = interpolate(
      t,
      [fireAt, fireAt + fireEl.beat("flash")],
      [0, 1],
      CLAMP,
    );
    const primary = i === primaryToken;
    const border =
      primary && fire > 0
        ? accent
        : rgba(fg, (0.08 + 0.14 * split) * (1 - fire * 0.3));
    const line = interpolate(
      t,
      [fireAt, fireAt + fireEl.beat("lead")],
      [0, 1],
      {
        ...CLAMP,
        easing: EASE_OUT,
      },
    );
    return (
      <div key={`t${i}`}>
        <div
          style={{
            position: "absolute",
            left: rest.x,
            top: rest.y - (tokSize * 1.5) / 2,
            width: tokW[i],
            height: tokSize * 1.5,
            transformOrigin: "0% 50%",
            transform: `${shift(x - rest.x, y - rest.y)}scale(${sc}) translateY(${lift}px)${glide(moving)}`,
            opacity: appear,
            borderRadius: 8 * u,
            border: `${Math.max(1, u)}px solid ${border}`,
            background: split > 0 ? p.token : "transparent",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontFamily: mono,
            fontWeight: 400,
            fontSize: tokSize,
            letterSpacing: "0em",
            color: ink ?? rgba(fg, 0.92),
            whiteSpace: "nowrap",
          }}
        >
          {tk}
        </div>
        <div
          style={{
            position: "absolute",
            left: rest.endX + tokW[i] * colScale + 6 * u,
            top: rest.node.y - 0.5 * u,
            width: Math.max(0, node.x - endX - tokW[i] * colScale - 12 * u),
            height: Math.max(1, u),
            transformOrigin: "0% 50%",
            transform: `${shift(endX - rest.endX, node.y - rest.node.y)}scaleX(${line})`,
            background: primary ? accent : rgba(fg, 0.3),
            opacity:
              fly >= 1
                ? 1 -
                  interpolate(
                    t,
                    [
                      fireEl.start + fireEl.beat("dim"),
                      fireEl.start + fireEl.beat("dimEnd"),
                    ],
                    [0, 0.6],
                    CLAMP,
                  )
                : 0,
          }}
        />
      </div>
    );
  });

  // ---- nodes (HTML for real depth-of-field blur)
  const nodeEls: React.ReactNode[] = [];
  for (const [k, layer] of layers.entries()) {
    if (k === outK) continue;
    for (const [i] of layer.entries()) {
      const pr = proj[k][i];
      const { lit, bloom } = nodeLit(k, i);
      const path = onPath(k, i) && lit > 0;
      const r = 5.2 * u * pr.s * (1 + bloom * 0.45);
      const prR = camRest.proj[k][i];
      const rR = 5.2 * u * prR.s * (1 + nodeLit(k, i, T_REST).bloom * 0.45);
      const dof = Math.abs(pr.s - 1) * 15 * u;
      const col = path ? accent : rgba(fg, 0.26 + 0.74 * lit ** 1.5);
      nodeEls.push(
        <div
          key={`n${k}-${i}`}
          style={{
            position: "absolute",
            left: prR.x - rR,
            top: prR.y - rR,
            transform:
              shift(pr.x - r - (prR.x - rR), pr.y - r - (prR.y - rR)) ||
              undefined,
            width: r * 2,
            height: r * 2,
            borderRadius: "50%",
            background: col,
            opacity: intro(k, i),
            filter: dof > 0.4 ? `blur(${dof}px)` : undefined,
            boxShadow: `0 0 0 ${r * 1.4 * bloom}px ${path ? `${accent}22` : rgba(fg, 0.07 * bloom)}`,
          }}
        />,
      );
    }
  }

  // ---- output node: fires, blooms, settles into the mark's dot
  const outFire = arrival(outK, hops);
  const outIn = intro(outK, 0);
  const outLit = interpolate(t, [outFire, outFire + 4], [0, 1], CLAMP);
  const dotR = 5.5 * u;
  const ringP = interpolate(t, [outFire, outFire + 26], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  // the node rides round the R's outline, then the mark fills behind it
  const outGeo = (tt: number, c: Cam) => {
    const outP = c.proj[outK][0];
    const outBloom = interpolate(
      tt,
      [outFire, outFire + 6, outFire + 22],
      [0, 1, 0],
      CLAMP,
    );
    const traceP = interpolate(tt, [trace.start, trace.end], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
    const headPt =
      !logo && traceP > 0
        ? getPointAtLength(REMOCN_R_PATH, traceP * R_LEN)
        : null;
    const head = headPt ? toScreen(headPt) : null;
    return {
      outP,
      outBloom,
      outR:
        interpolate(c.resolveP, [0, 1], [7 * u * outP.s, dotR]) *
        (1 + outBloom * 0.5),
      traceP,
      head,
      nodeX: head ? head.x : outP.x,
      nodeY: head ? head.y : outP.y,
    };
  };
  const { outP, outBloom, outR, traceP, head, nodeX, nodeY } = outGeo(t, cam);
  const outRest = outGeo(T_REST, camRest);
  const fillP = interpolate(
    t,
    [T_TRACE + trace.beat("fill"), T_TRACE + trace.beat("fillEnd")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );
  const nodeFade = logo
    ? 1 -
      interpolate(t, [T_TRACE, T_TRACE + trace.beat("logoFade")], [0, 1], CLAMP)
    : 1 -
      interpolate(
        t,
        [T_TRACE + trace.beat("fade"), T_TRACE + trace.beat("fadeEnd")],
        [0, 1],
        CLAMP,
      );
  const strokeO =
    interpolate(t, [T_TRACE, T_TRACE + trace.beat("strokeIn")], [0, 1], CLAMP) *
    (1 -
      interpolate(
        t,
        [
          T_TRACE + trace.beat("strokeOut"),
          T_TRACE + trace.beat("strokeOutEnd"),
        ],
        [0, 1],
        CLAMP,
      ));
  const nameP = interpolate(t, [nameEl.start, nameEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const fgSolid = ink ?? rgba(fg, 1);
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const gradId = `rfill${uid}`;

  // beam ground: rises behind the lockup as the network resolves
  const beamUp = 0.45 + 0.55 * resolveP;
  const beamY = 104 - resolveP * 8 + Math.sin(t / 40) * 1.2;
  const [b0, b1, b2] = p.beam;
  const beamBg = [
    `radial-gradient(40% 24% at 50% ${56 + (1 - resolveP) * 4}%, rgba(${b1[0]},${b1[1]},${b1[2]},${b1[3] * resolveP * 0.8}) 0%, transparent 75%)`,
    `radial-gradient(24% 62% at ${50 + Math.sin(t / 55) * 1.2}% ${beamY}%, rgba(${b2[0]},${b2[1]},${b2[2]},${b2[3] * beamUp}) 0%, transparent 72%)`,
    `radial-gradient(60% 70% at 50% ${beamY + 6}%, rgba(${b1[0]},${b1[1]},${b1[2]},${b1[3] * beamUp * 0.7}) 0%, transparent 72%)`,
    `radial-gradient(90% 80% at 50% 38%, rgba(${b0[0]},${b0[1]},${b0[2]},${b0[3]}) 0%, transparent 78%)`,
  ].join(", ");

  const rTransform = `translate(${markLeft} ${markTop}) scale(${rk})`;
  const wordX = markLeft + markW + gap;

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : (background ?? p.bg),
        overflow: "hidden",
      }}
    >
      {!transparent ? <AbsoluteFill style={{ background: beamBg }} /> : null}

      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            filter: netBlur > 0.2 ? `blur(${netBlur * u}px)` : undefined,
            opacity: netOpacity,
          }}
        >
          <svg
            width={width}
            height={height}
            style={{ position: "absolute", inset: 0 }}
            aria-hidden
          >
            {edgeEls}
            {pulseEls}
          </svg>
          {nodeEls}
        </AbsoluteFill>
        <AbsoluteFill
          style={{
            filter: resolveP > 0.01 ? `blur(${resolveP * 5 * u}px)` : undefined,
            opacity: netOpacity,
          }}
        >
          {tokenEls}
        </AbsoluteFill>

        {/* lockup: R outline traced by the node, gradient fill, then "emocn" */}
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0, overflow: "visible" }}
          aria-hidden
        >
          <defs>
            <linearGradient
              id={gradId}
              gradientUnits="userSpaceOnUse"
              x1={R_W * (0.2 + 0.06 * Math.sin(t / 45))}
              y1={0}
              x2={R_W * 0.55}
              y2={R_H}
            >
              <stop offset="0%" stopColor={p.rFill[0]} />
              <stop offset="58%" stopColor={p.rFill[1]} />
              <stop offset="100%" stopColor={p.rFill[2]} />
            </linearGradient>
          </defs>
          {!logo && (
            <g transform={rTransform}>
              <path
                d={REMOCN_R_PATH}
                fill={`url(#${gradId})`}
                opacity={fillP}
              />
              {strokeO > 0 && (
                <path
                  d={REMOCN_R_PATH}
                  fill="none"
                  stroke={rgba(fg, 1)}
                  strokeWidth={(1 * u) / rk}
                  opacity={strokeO * 0.16 * (1 - fillP)}
                />
              )}
              {strokeO > 0 && (
                <path
                  d={REMOCN_R_PATH}
                  fill="none"
                  stroke={accent}
                  strokeWidth={(2.2 * u) / rk}
                  strokeLinejoin="round"
                  pathLength={1}
                  strokeDasharray={`${traceP} 2`}
                  opacity={strokeO}
                />
              )}
            </g>
          )}
        </svg>
        {logo ? (
          <div
            style={{
              position: "absolute",
              left: markLeft,
              top: markTop,
              width: markW,
              height: markH,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              opacity: interpolate(
                t,
                [T_TRACE, T_TRACE + trace.beat("logoIn")],
                [0, 1],
                CLAMP,
              ),
            }}
          >
            {logo}
          </div>
        ) : null}
        <svg
          width={width}
          height={height}
          style={{
            position: "absolute",
            inset: 0,
            opacity: nameP,
            filter: nameP < 0.98 ? `blur(${(1 - nameP) * 8 * u}px)` : undefined,
            transform: `translateX(${(1 - nameP) * -14 * u}px)`,
          }}
          aria-hidden
        >
          <text
            x={wordX}
            y={baselineY}
            fill={fgSolid}
            style={{
              fontFamily,
              fontWeight: brand ? 600 : 500,
              fontSize: nameSize,
              letterSpacing: `${0.05 - nameP * 0.075}em`,
            }}
          >
            {word}
          </text>
        </svg>

        {/* output node: stays sharp, it is where focus lands */}
        <div
          style={{
            position: "absolute",
            left: outRest.outP.x - outRest.outR * 4,
            top: outRest.outP.y - outRest.outR * 4,
            width: outR * 8,
            height: outR * 8,
            borderRadius: "50%",
            border: `${Math.max(1, u)}px solid ${accent}`,
            transform: `${shift(
              outP.x - outR * 4 - (outRest.outP.x - outRest.outR * 4),
              outP.y - outR * 4 - (outRest.outP.y - outRest.outR * 4),
            )}scale(${0.25 + ringP * 0.75})`,
            opacity: (1 - ringP) * 0.5 * outLit,
          }}
        />
        <div
          style={{
            position: "absolute",
            left: outRest.nodeX - outRest.outR,
            top: outRest.nodeY - outRest.outR,
            transform:
              shift(
                nodeX - outR - (outRest.nodeX - outRest.outR),
                nodeY - outR - (outRest.nodeY - outRest.outR),
              ) || undefined,
            width: outR * 2,
            height: outR * 2,
            borderRadius: "50%",
            background: outLit > 0 ? accent : rgba(fg, 0.35),
            opacity: outIn * nodeFade,
            boxShadow: `0 0 0 ${outR * 0.9 * Math.max(outBloom, head ? 0.6 : 0)}px ${accent}2E`,
          }}
        />
      </ScaleLayer>

      {!transparent && grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The prompt types in token by token while the network fades in and the
// camera drifts; the tokens split apart, fly to the input nodes and fire, the
// pulse hops layer by layer, the camera resolves onto the output node, which
// traces the R before the name reveals. Frames on the 30 fps scene timeline,
// after `delay` and `speed`. The ids are public: a saved `timing` prop refers
// to them.

export type NeuralPulseElementId =
  | `token:${number}`
  | "drift"
  | "network"
  | "split"
  | "fly"
  | "fire"
  | `layer:${number}`
  | "resolve"
  | "trace"
  | "name";

export interface NeuralPulseTimingProps {
  input?: string;
  hop?: number;
}

export const DEFAULT_INPUT = "Make a launch film";
/** Hidden layer sizes; the pulse leaves each layer but the output. */
export const HIDDEN = [6, 7, 5];
export const DEFAULT_HOP = 15;
const T_SPLIT = 16;
const T_FLY = 30;
const T_FIRE = 54;
const T_HOP0 = 62;
const TRAVEL = 13;

/** The prompt's tokens, at most five. */
export function inputTokens(input: string) {
  return input.split(/\s+/).filter(Boolean).slice(0, 5);
}

// Tokens appear as a chain. The network fades in node by node from its
// start (`layer` frames per layer, `node` per node, `fade` each) while its
// blur clears between `focusFrom` and `focusTo`. The fly sends token i off
// `stagger * i` frames after its start, each flight `flight` long; the fire
// flashes token i `stagger * i` after its start over `flash`, draws its lead
// over `lead` and dims the leads between `dim` and `dimEnd`. Each layer's
// pulse travels its edges in `travel` and lights the next layer at `arrive`.
// The resolve pulls the camera in from `pull` to its end; the trace runs
// round the R over its length, the mark fills between `fill` and `fillEnd`
// and the node and stroke fade on their beats.
export const neuralPulseTimeline = defineTimeline<
  NeuralPulseElementId,
  NeuralPulseTimingProps
>(({ input = DEFAULT_INPUT, hop = DEFAULT_HOP }) => {
  const tokens = inputTokens(input);
  const elements: TimelineElement<NeuralPulseElementId>[] = tokens.map(
    (token, i) => ({
      id: `token:${i}` as const,
      lane: "Tokens",
      label: token,
      start: i * 2,
      length: 12,
      follows: i > 0 ? (`token:${i - 1}` as const) : undefined,
    }),
  );
  elements.push(
    {
      id: "drift",
      lane: "Camera",
      label: "Camera drifts",
      start: 0,
      length: 200,
    },
    {
      id: "network",
      lane: "Network",
      label: "Network fades in",
      start: 2,
      length: 20,
      beats: { layer: 4, node: 1.5, focusFrom: -2, focusTo: 42 },
    },
    {
      id: "split",
      lane: "Tokens",
      label: "Tokens split",
      start: T_SPLIT,
      length: 12,
    },
    {
      id: "fly",
      lane: "Tokens",
      label: "Tokens fly to the inputs",
      start: T_FLY,
      length: 3 * Math.max(0, tokens.length - 1) + 22,
      follows: "split",
      beats: { stagger: 3, flight: 22 },
    },
    {
      id: "fire",
      lane: "Tokens",
      label: "Tokens fire",
      start: T_FIRE,
      length: T_HOP0 - T_FIRE,
      follows: "fly",
      beats: { stagger: 2, flash: 6, lead: 8, dim: 20, dimEnd: 40 },
    },
  );
  const layers = 1 + HIDDEN.length;
  for (let k = 0; k < layers; k++) {
    elements.push({
      id: `layer:${k}`,
      lane: "Network",
      label: k === 0 ? "Pulse leaves the inputs" : `Pulse hops layer ${k}`,
      start: T_HOP0 + k * hop,
      length: hop,
      follows: k > 0 ? `layer:${k - 1}` : "fire",
      beats: { travel: TRAVEL, arrive: TRAVEL + 2 },
    });
  }
  const resolveAt = T_HOP0 + 4 * hop;
  const traceAt = resolveAt + 32;
  elements.push(
    {
      id: "resolve",
      lane: "Camera",
      label: "Camera resolves",
      start: resolveAt,
      length: 32,
      follows: `layer:${layers - 1}`,
      beats: { pull: 2 },
    },
    {
      id: "trace",
      lane: "Logo",
      label: "Node traces the R",
      start: traceAt,
      length: 34,
      follows: "resolve",
      beats: {
        strokeIn: 4,
        logoIn: 14,
        logoFade: 12,
        fill: 18,
        fillEnd: 42,
        fade: 32,
        fadeEnd: 44,
        strokeOut: 34,
        strokeOutEnd: 50,
      },
    },
    {
      id: "name",
      lane: "Logo",
      label: "Name reveals",
      start: traceAt + 20,
      length: 32,
      follows: "trace",
    },
  );
  return elements.sort((a, b) => a.start - b.start);
});
